using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Globalization;
using System.IO;
using System.Text.RegularExpressions;
using System.Windows.Forms;
namespace ZenForms.Core
{
    public sealed class ZenGCodeErrorEventArgs : EventArgs { public string Message { get; private set; } public ZenGCodeErrorEventArgs(string message) { Message = message; } }
    [Category("ZenForms Modern Components")]
    [Description("G-Code 3D Viewer for print.")]
    public class ZenGCodePreview : UserControl
    {
        private sealed class Segment { public double X1, Y1, X2, Y2, Z; public bool Extrude; public int Layer; }
        private readonly List<Segment> segments = new List<Segment>(); private readonly TrackBar layerSlider; private readonly Label info; private readonly Surface view; private int layer = -1; private bool showTravel = true; private bool isometric; private double zoom = 1; private float panX, panY; private Point last; private bool dragging; private double minX, maxX, minY, maxY;
        [Category("ZenForms GCode"), DefaultValue(true)] public bool ShowTravel { get { return showTravel; } set { showTravel = value; view.Invalidate(); } }
        [Category("ZenForms GCode"), DefaultValue(false)] public bool IsometricView { get { return isometric; } set { isometric = value; view.Invalidate(); } }
        [Browsable(false)] public int LayerCount { get { return segments.Count == 0 ? 0 : segments[segments.Count - 1].Layer + 1; } }
        [Browsable(false)] public int CurrentLayer { get { return layer; } }
        public event EventHandler<ZenGCodeErrorEventArgs> LoadError;
        public ZenGCodePreview() { Size = new Size(760, 520); BackColor = ZenTheme.Background; Panel toolbar = new Panel { Dock = DockStyle.Top, Height = 43, BackColor = ZenTheme.Surface }; Button open = new Button { Dock = DockStyle.Left, Width = 105, Text = "Open G-code…", FlatStyle = FlatStyle.Flat, BackColor = ZenTheme.SurfaceRaised, ForeColor = ZenTheme.Foreground }; Button viewMode = new Button { Dock = DockStyle.Right, Width = 105, Text = "View XY / iso", FlatStyle = FlatStyle.Flat, BackColor = ZenTheme.SurfaceRaised, ForeColor = ZenTheme.Foreground }; info = new Label { Dock = DockStyle.Fill, Text = "Open .gcode, .gco ou .gc", ForeColor = ZenTheme.Muted, TextAlign = ContentAlignment.MiddleLeft, Padding = new Padding(9, 0, 0, 0) }; toolbar.Controls.Add(info); toolbar.Controls.Add(viewMode); toolbar.Controls.Add(open); layerSlider = new TrackBar { Dock = DockStyle.Bottom, Height = 42, Minimum = 0, Maximum = 0, TickStyle = TickStyle.None, BackColor = ZenTheme.Surface }; view = new Surface(this) { Dock = DockStyle.Fill, BackColor = Color.FromArgb(12, 16, 28) }; Controls.Add(view); Controls.Add(layerSlider); Controls.Add(toolbar); open.Click += (s, e) => OpenFile(); viewMode.Click += (s, e) => IsometricView = !IsometricView; layerSlider.ValueChanged += (s, e) => { layer = layerSlider.Value; UpdateInfo(); view.Invalidate(); }; }
        public void LoadGCode(string path) { try { segments.Clear(); double x = 0, y = 0, z = 0, ePos = 0; HashSet<double> zs = new HashSet<double>(); foreach (string raw in File.ReadLines(path)) { string line = raw; int comment = line.IndexOf(';'); if (comment >= 0) line = line.Substring(0, comment); line = Regex.Replace(line, "\\([^)]*\\)", "").Trim().ToUpperInvariant(); if (line.Length == 0) continue; Match cmd = Regex.Match(line, "^G\\s*(\\d+)"); if (!cmd.Success) continue; int g = int.Parse(cmd.Groups[1].Value, CultureInfo.InvariantCulture); if (g != 0 && g != 1) continue; double nx = x, ny = y, nz = z, ne = ePos; foreach (Match m in Regex.Matches(line, "([XYZE])\\s*([-+]?(?:\\d*\\.)?\\d+)", RegexOptions.CultureInvariant)) { double v = Double.Parse(m.Groups[2].Value, CultureInfo.InvariantCulture); switch (m.Groups[1].Value) { case "X": nx = v; break; case "Y": ny = v; break; case "Z": nz = v; break; case "E": ne = v; break; } } if (nz != z) zs.Add(Math.Round(nz, 3)); bool moved = nx != x || ny != y; bool extrusion = ne > ePos; if (moved) { segments.Add(new Segment { X1 = x, Y1 = y, X2 = nx, Y2 = ny, Z = nz, Extrude = extrusion }); } x = nx; y = ny; z = nz; ePos = ne; } if (segments.Count == 0) throw new InvalidDataException("Any move G0/G1 with X/Y was found."); List<double> levels = new List<double>(zs); levels.Sort(); if (levels.Count == 0) levels.Add(z); for (int i = 0; i < segments.Count; i++) { int idx = levels.FindIndex(v => Math.Abs(v - segments[i].Z) < .002); segments[i].Layer = Math.Max(0, idx); } minX = Double.PositiveInfinity; minY = Double.PositiveInfinity; maxX = Double.NegativeInfinity; maxY = Double.NegativeInfinity; foreach (Segment s in segments) { minX = Math.Min(minX, Math.Min(s.X1, s.X2)); maxX = Math.Max(maxX, Math.Max(s.X1, s.X2)); minY = Math.Min(minY, Math.Min(s.Y1, s.Y2)); maxY = Math.Max(maxY, Math.Max(s.Y1, s.Y2)); } layerSlider.Maximum = Math.Max(0, LayerCount - 1); layer = layerSlider.Maximum; layerSlider.Value = layer; zoom = 1; panX = panY = 0; UpdateInfo(); view.Invalidate(); } catch (Exception ex) { segments.Clear(); view.Invalidate(); EventHandler<ZenGCodeErrorEventArgs> h = LoadError; if (h != null) h(this, new ZenGCodeErrorEventArgs(ex.Message)); else MessageBox.Show(FindForm(), ex.Message, "ZenGCodePreview", MessageBoxButtons.OK, MessageBoxIcon.Warning); } }
        private void OpenFile() { using (OpenFileDialog d = new OpenFileDialog { Filter = "G-code|*.gcode;*.gco;*.gc|All|*.*", CheckFileExists = true }) if (d.ShowDialog(FindForm()) == DialogResult.OK) LoadGCode(d.FileName); }
        private void UpdateInfo() { if (segments.Count == 0) { info.Text = "Open .gcode, .gco ou .gc"; return; } int count = 0; foreach (Segment s in segments) if (s.Layer <= layer) count++; info.Text = String.Format(CultureInfo.InvariantCulture, "Layer {0}/{1}   •   {2:N0} moves   •   X {3:0.0}–{4:0.0} mm   Y {5:0.0}–{6:0.0} mm", layer + 1, LayerCount, count, minX, maxX, minY, maxY); }
        private sealed class Surface : Control { private readonly ZenGCodePreview owner; public Surface(ZenGCodePreview o) { owner = o; SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true); } protected override void OnMouseDown(MouseEventArgs e) { base.OnMouseDown(e); if (e.Button == MouseButtons.Left) { owner.dragging = true; owner.last = e.Location; Capture = true; } } protected override void OnMouseUp(MouseEventArgs e) { base.OnMouseUp(e); owner.dragging = false; Capture = false; } protected override void OnMouseMove(MouseEventArgs e) { base.OnMouseMove(e); if (owner.dragging) { owner.panX += e.X - owner.last.X; owner.panY += e.Y - owner.last.Y; owner.last = e.Location; Invalidate(); } } protected override void OnMouseWheel(MouseEventArgs e) { base.OnMouseWheel(e); owner.zoom = Math.Max(.2, Math.Min(10, owner.zoom * (e.Delta > 0 ? 1.12 : .89))); Invalidate(); } protected override void OnPaint(PaintEventArgs e) { base.OnPaint(e); Graphics g = e.Graphics; g.SmoothingMode = SmoothingMode.AntiAlias; g.Clear(BackColor); if (owner.segments.Count == 0) { TextRenderer.DrawText(g, "The file paths will be rendered here", Font, ClientRectangle, ZenTheme.Muted, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter); return; } float margin = 35; double sx = (Width - margin * 2) / Math.Max(.01, owner.maxX - owner.minX), sy = (Height - margin * 2) / Math.Max(.01, owner.maxY - owner.minY); float scale = (float)Math.Min(sx, sy) * (float)owner.zoom; float ox = Width / 2f - (float)((owner.minX + owner.maxX) / 2) * scale + owner.panX, oy = Height / 2f + (float)((owner.minY + owner.maxY) / 2) * scale + owner.panY; using (Pen grid = new Pen(Color.FromArgb(28, 130, 145, 165))) for (int i = -10; i <= 10; i++) { float d = i * 10 * scale; g.DrawLine(grid, ox + d, 0, ox + d, Height); g.DrawLine(grid, 0, oy + d, Width, oy + d); } using (Pen extrusionPen = new Pen(Color.FromArgb(245, ZenTheme.Accent), 1.7f)) using (Pen travelPen = new Pen(Color.FromArgb(80, ZenTheme.Muted), .8f)) { travelPen.DashPattern = new float[] { 2, 3 }; foreach (Segment s in owner.segments) { if (s.Layer > owner.layer || (!owner.showTravel && !s.Extrude)) continue; float x1, y1, x2, y2; if (owner.isometric) { x1 = ox + (float)(s.X1 - s.Y1 * .55) * scale; y1 = oy - (float)((s.X1 + s.Y1) * .32 + s.Z) * scale; x2 = ox + (float)(s.X2 - s.Y2 * .55) * scale; y2 = oy - (float)((s.X2 + s.Y2) * .32 + s.Z) * scale; } else { x1 = ox + (float)s.X1 * scale; y1 = oy - (float)s.Y1 * scale; x2 = ox + (float)s.X2 * scale; y2 = oy - (float)s.Y2 * scale; } g.DrawLine(s.Extrude ? extrusionPen : travelPen, x1, y1, x2, y2); } } } }
    }
}
